package com.huy.enterprise.shipment;
import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.ShipmentStatus; import com.huy.enterprise.order.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class ShipmentService{private final ShipmentRepository repository;private final PurchaseOrderRepository orders;public List<ShipmentResponse> all(){return repository.findAll().stream().map(ShipmentResponse::from).toList();}public ShipmentResponse one(UUID id){return ShipmentResponse.from(get(id));}@Transactional public ShipmentResponse create(CreateShipmentRequest r){if(repository.existsByShipmentCode(r.shipmentCode()))throw new ConflictException("Shipment code already exists: "+r.shipmentCode());Shipment s=new Shipment();s.setShipmentCode(r.shipmentCode());s.setStatus(r.status()==null?ShipmentStatus.PENDING:r.status());apply(s,r.purchaseOrderId(),r.carrierName(),r.departureDate(),r.expectedArrivalDate(),r.actualArrivalDate(),r.currentLocation(),r.notes());return ShipmentResponse.from(repository.save(s));}@Transactional public ShipmentResponse update(UUID id,UpdateShipmentRequest r){Shipment s=get(id);apply(s,r.purchaseOrderId(),r.carrierName(),r.departureDate(),r.expectedArrivalDate(),r.actualArrivalDate(),r.currentLocation(),r.notes());return ShipmentResponse.from(repository.save(s));}@Transactional public ShipmentResponse status(UUID id,ShipmentStatus status){Shipment s=get(id);s.setStatus(status);return ShipmentResponse.from(repository.save(s));}private Shipment get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Shipment not found: "+id));}private void apply(Shipment s,UUID orderId,String carrier,java.time.LocalDate departure,java.time.LocalDate expected,java.time.LocalDate actual,String location,String notes){s.setPurchaseOrder(orders.findById(orderId).orElseThrow(()->new ResourceNotFoundException("Purchase order not found: "+orderId)));s.setCarrierName(carrier);s.setDepartureDate(departure);s.setExpectedArrivalDate(expected);s.setActualArrivalDate(actual);s.setCurrentLocation(location);s.setNotes(notes);}}
